using System.Security.Claims; using Microsoft.AspNetCore.Authentication; using Microsoft.AspNetCore.Authentication.Cookies; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.RateLimiting;
namespace GpSelect.Api; [ApiController][Route("api/admin/auth")] public class AuthController(IConfiguration cfg):ControllerBase { [HttpPost("login")][EnableRateLimiting("login")] public async Task<IActionResult> Login(LoginRequest r){ var hash=cfg["Admin:PasswordHash"]; var valid=!string.IsNullOrWhiteSpace(hash)&&new PasswordHasher<object>().VerifyHashedPassword(null!,hash,r.Password)!=PasswordVerificationResult.Failed; if(!valid||!string.Equals(r.Email,cfg["Admin:Email"],StringComparison.OrdinalIgnoreCase)) return Problem(statusCode:401,title:"Invalid credentials"); await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(new[]{new Claim(ClaimTypes.Name,r.Email),new Claim(ClaimTypes.Role,"Admin")},CookieAuthenticationDefaults.AuthenticationScheme))); return Ok(new{authenticated=true}); } [HttpPost("logout")][Authorize] public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return NoContent();} [HttpGet("me")][Authorize] public IActionResult Me()=>Ok(new{email=User.Identity?.Name,role="Admin"}); } public sealed record LoginRequest(string Email,string Password);


